quality.run:
for result in "$CHANGES_RESULT" "$REPO_RESULT" "$UI_RESULT" "$PERSONA_WEB_E2E_RESULT" "$NATIVE_MUSIC_RESULT" "$MOBILE_RESULT" "$BACKEND_RESULT" "$NATIVE_ANDROID_RESULT"; do
  case "$result" in
    success|skipped) ;;
    *) echo "Selected quality job did not pass: $result" >&2; exit 1 ;;
  esac
done
